sys_variable_value.value:
(function execute(inputs, outputs) {
    var requestType = inputs.request_type || '';
    var priority = inputs.priority || '';

    try {
        // Map actual table choice values to Assignment Matrix condition values
        var dtRequestType = requestType;
        if (requestType === 'health_inpection') {
            dtRequestType = 'general_health';
        } else if (requestType === 'medical_assistance') {
            dtRequestType = 'medical assistance';
        } else if (requestType === 'emergency_support') {
            dtRequestType = 'emergency';
        }

        var dtApi = new sn_dt.DecisionTableAPI();
        var dtInputs = {
            u_request_type: dtRequestType,
            u_priority: priority
        };
        var result = dtApi.getDecision('9f5da86ac32647101ff35d02b4013121', dtInputs);

        if (result && result.length > 0) {
            var decision = result[0];
            if (decision.u_assignment_group) {
                var groupValue = decision.u_assignment_group.toString();
                var grp = new GlideRecord('sys_user_group');
                if (grp.get(groupValue)) {
                    outputs.assignment_group_name = grp.getValue('name');
                } else {
                    outputs.assignment_group_name = groupValue;
                }
            } else {
                outputs.assignment_group_name = 'Health Support';
            }
        } else {
            outputs.assignment_group_name = 'Health Support';
        }
    } catch (e) {
        gs.error('Determine Assignment Group - Error: ' + e.message);
        outputs.assignment_group_name = 'Health Support';
    }
})(inputs, outputs);

